-- 052 · Tłumaczenia treści etapów (en, de, uk, es)
--
-- WYGENEROWANE: node scripts/content-i18n.mjs build — nie edytować ręcznie.
-- Źródło: supabase/content/i18n/<język>/<etap>-v1.json. Wymaga 049.
-- Idempotentne: każde odpalenie ustawia `translations` od nowa; wiersze
-- bez tłumaczeń dostają '{}', więc usunięte tłumaczenie też znika z bazy.

begin;

-- ═══ ambition v1 ═══
update public.stage_templates t set translations = '{"en":{"title":"Ambition Stage","subtitle":"Your first idea","intro":"When did you last think: “There has to be an easier way”? In a moment you''ll pick one such situation, come up with a way to improve it and give your project a name. Approximate time: 10–15 minutes. Short answers are enough. You can change everything later.","finish_label":"I''m checking my idea"},"de":{"title":"Ambition Stage","subtitle":"Deine erste Idee","intro":"Wann hast du zuletzt gedacht: „Das muss doch einfacher gehen“? Gleich wählst du eine solche Situation aus, überlegst dir, wie man sie verbessern könnte, und gibst deinem Projekt einen Namen. Dauer: etwa 10–15 Minuten. Kurze Antworten reichen. Du kannst später alles ändern.","finish_label":"Ich prüfe meine Idee"},"uk":{"title":"Ambition Stage","subtitle":"Твоя перша ідея","intro":"Коли тобі востаннє спадало на думку: «Мабуть, є простіший спосіб»? Зараз ти вибереш одну таку ситуацію, придумаєш, як її покращити, і даси своєму проєкту назву. Орієнтовний час: 10–15 хвилин. Достатньо коротких відповідей. Усе можна змінити пізніше.","finish_label":"Перевіряю свою ідею"},"es":{"title":"Ambition Stage","subtitle":"Tu primera idea","intro":"¿Cuándo pensaste por última vez: «Tiene que haber una forma más fácil»? Enseguida elegirás una situación así, pensarás cómo mejorarla y le pondrás nombre a tu proyecto. Tiempo aproximado: 10–15 minutos. Bastan respuestas cortas. Podrás cambiarlo todo más adelante.","finish_label":"Pongo a prueba mi idea"}}'::jsonb
  where t.key = 'ambition' and t.version = 1;
update public.stage_categories c set translations = '{"en":{"title":"Your first idea"},"de":{"title":"Deine erste Idee"},"uk":{"title":"Твоя перша ідея"},"es":{"title":"Tu primera idea"}}'::jsonb
  from public.stage_templates t where c.template_id = t.id and t.key = 'ambition' and t.version = 1 and c.key = 'general';
update public.stage_points p set translations = '{"en":{"title":"Pick something you want to change","duration_hint":"About 3 minutes","guide_body":"Don''t look for a breakthrough idea. Look for a situation that genuinely annoys someone — ideally one you know from your own experience. The more specific the situation, the easier it will be to check later. “People waste time” is too broad. “A café owner throws away unsold sandwiches every day” is something you can ask a specific person about."},"de":{"title":"Wähle etwas, das du ändern willst","duration_hint":"Etwa 3 Minuten","guide_body":"Such keine bahnbrechende Idee. Such eine Situation, die jemanden wirklich nervt — am besten eine, die du aus eigener Erfahrung kennst. Je konkreter die Situation, desto leichter lässt sie sich später überprüfen. „Menschen verlieren Zeit“ ist zu allgemein. „Die Inhaberin eines Cafés wirft jeden Tag unverkaufte Sandwiches weg“ ist etwas, wonach man eine konkrete Person fragen kann."},"uk":{"title":"Вибери те, що хочеш змінити","duration_hint":"Близько 3 хвилин","guide_body":"Не шукай проривної ідеї. Шукай ситуацію, яка когось справді дратує — найкраще таку, яку знаєш із власного досвіду. Що конкретніша ситуація, то легше буде її потім перевірити. «Люди втрачають час» — надто широко. «Власниця кав''ярні щодня викидає непродані сендвічі» — це те, про що можна запитати конкретну людину."},"es":{"title":"Elige algo que quieras cambiar","duration_hint":"Unos 3 minutos","guide_body":"No busques una idea revolucionaria. Busca una situación que de verdad moleste a alguien — mejor si la conoces por experiencia propia. Cuanto más concreta sea, más fácil será comprobarla después. «La gente pierde tiempo» es demasiado amplio. «La dueña de una cafetería tira cada día los bocadillos que no ha vendido» es algo que se le puede preguntar a una persona concreta."}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'ambition' and t.version = 1
    and c.key = 'general' and p.key = 'pick-change';
update public.stage_subpoints s set translations = '{"en":{"title":"Catch a problem"},"de":{"title":"Halte das Problem fest"},"uk":{"title":"Зафіксуй проблему"},"es":{"title":"Atrapa el problema"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'ambition' and t.version = 1
    and c.key = 'general' and p.key = 'pick-change' and s.key = 'catch-problem';
update public.stage_fields f set translations = '{"en":{"question":"What has recently been difficult, expensive, annoying or too time-consuming for you or someone you know? Pick one situation.","help":"Think back over the last week: work, study, shopping, hobbies or chores. What had to be fixed, took a long time to sort out or had to be done several times?","example":"At the café where I work, unsold sandwiches are left over at the end of the day."},"de":{"question":"Was war für dich oder jemanden, den du kennst, zuletzt schwierig, teuer, nervig oder hat zu viel Zeit gekostet? Wähle eine Situation aus.","help":"Denk an die letzte Woche: Arbeit, Studium, Einkäufe, Hobbys oder Pflichten. Was musste man korrigieren, lange erledigen oder mehrmals machen?","example":"In dem Café, in dem ich arbeite, bleiben am Ende des Tages unverkaufte Sandwiches übrig."},"uk":{"question":"Що останнім часом було для тебе або когось, кого ти знаєш, складним, дорогим, дратівливим чи забирало забагато часу? Вибери одну ситуацію.","help":"Згадай останній тиждень: роботу, навчання, покупки, хобі чи обов''язки. Що доводилося виправляти, довго залагоджувати або робити кілька разів?","example":"У кав''ярні, де я працюю, наприкінці дня залишаються непродані сендвічі."},"es":{"question":"¿Qué ha sido últimamente difícil, caro, molesto o ha llevado demasiado tiempo para ti o para alguien que conoces? Elige una situación.","help":"Piensa en la última semana: trabajo, estudios, compras, aficiones u obligaciones. ¿Qué hubo que corregir, tardó mucho en resolverse o hubo que hacer varias veces?","example":"En la cafetería donde trabajo, al final del día sobran bocadillos sin vender."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'ambition' and t.version = 1 and c.key = 'general' and p.key = 'pick-change'
    and s.key = 'catch-problem' and f.key = 'problem';
update public.stage_subpoints s set translations = '{"en":{"title":"Say who you want to help"},"de":{"title":"Sag, wem du helfen willst"},"uk":{"title":"Вкажи, кому хочеш допомогти"},"es":{"title":"Indica a quién quieres ayudar"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'ambition' and t.version = 1
    and c.key = 'general' and p.key = 'pick-change' and s.key = 'who-to-help';
update public.stage_fields f set translations = '{"en":{"question":"Who is affected by the difficulty you picked?","help":"Name specific people or a type of company. You can start with yourself.","example":"Owners of small cafés that prepare food on site."},"de":{"question":"Wen betrifft die gewählte Schwierigkeit?","help":"Nenne konkrete Menschen oder eine Art von Unternehmen. Du kannst bei dir selbst anfangen.","example":"Inhaber kleiner Cafés, die Essen vor Ort zubereiten."},"uk":{"question":"Кого стосується вибрана проблема?","help":"Вкажи конкретних людей або тип компанії. Можна почати із себе.","example":"Власники невеликих кав''ярень, які готують їжу на місці."},"es":{"question":"¿A quién afecta la dificultad que has elegido?","help":"Indica personas concretas o un tipo de empresa. Puedes empezar por ti.","example":"Dueños de pequeñas cafeterías que preparan la comida en el local."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'ambition' and t.version = 1 and c.key = 'general' and p.key = 'pick-change'
    and s.key = 'who-to-help' and f.key = 'audience';
update public.stage_subpoints s set translations = '{"en":{"title":"Give the project a working name"},"de":{"title":"Gib dem Projekt einen Arbeitstitel"},"uk":{"title":"Дай проєкту робочу назву"},"es":{"title":"Ponle un nombre provisional al proyecto"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'ambition' and t.version = 1
    and c.key = 'general' and p.key = 'pick-change' and s.key = 'working-name';
update public.stage_fields f set translations = '{"en":{"question":"What do you want to call it for now?","help":"A simple phrase is enough, e.g. “The Last Sandwich”. If nothing comes to mind, leave “My first project”."},"de":{"question":"Wie willst du es vorerst nennen?","help":"Ein einfaches Stichwort reicht, z. B. „Letztes Sandwich“. Wenn dir nichts einfällt, lass „Mein erstes Projekt“ stehen."},"uk":{"question":"Як ти хочеш його поки що називати?","help":"Достатньо простого слова, напр. «Останній сендвіч». Якщо нічого не спадає на думку, залиш «Мій перший проєкт»."},"es":{"question":"¿Cómo quieres llamarlo por ahora?","help":"Basta con una palabra sencilla, p. ej. «El último bocadillo». Si no se te ocurre nada, deja «Mi primer proyecto»."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'ambition' and t.version = 1 and c.key = 'general' and p.key = 'pick-change'
    and s.key = 'working-name' and f.key = 'working_name';
update public.stage_points p set translations = '{"en":{"title":"Come up with a way to help","duration_hint":"About 4 minutes","guide_body":"The solution doesn''t have to be an app. It can be a service, a better way of organizing work, an object or simply doing something for someone. At this stage don''t judge whether the idea is good — write down two and pick the one that''s easier to check. Keep the other; you''ll come back to it if the first one doesn''t hold up."},"de":{"title":"Überleg dir, wie du helfen kannst","duration_hint":"Etwa 4 Minuten","guide_body":"Die Lösung muss keine App sein. Es kann eine Dienstleistung sein, eine bessere Arbeitsorganisation, ein Gegenstand oder einfach, etwas für jemanden zu erledigen. Bewerte jetzt noch nicht, ob die Idee gut ist — schreib zwei auf und wähle die, die sich leichter überprüfen lässt. Behalte die zweite; du kommst auf sie zurück, falls sich die erste nicht bewährt."},"uk":{"title":"Придумай, як допомогти","duration_hint":"Близько 4 хвилин","guide_body":"Рішенням не обов''язково має бути застосунок. Це може бути послуга, краща організація роботи, річ або просто виконання чогось за когось. На цьому етапі не оцінюй, чи ідея добра — запиши дві й вибери ту, яку легше перевірити. Другу збережи: повернешся до неї, якщо перша не витримає перевірки."},"es":{"title":"Piensa cómo ayudar","duration_hint":"Unos 4 minutos","guide_body":"La solución no tiene por qué ser una app. Puede ser un servicio, una mejor organización del trabajo, un objeto o simplemente hacer algo por otra persona. En esta etapa no valores si la idea es buena — apunta dos y elige la que sea más fácil de comprobar. Guarda la otra; volverás a ella si la primera no se sostiene."}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'ambition' and t.version = 1
    and c.key = 'general' and p.key = 'find-way';
update public.stage_subpoints s set translations = '{"en":{"title":"Find two ways"},"de":{"title":"Finde zwei Wege"},"uk":{"title":"Знайди два способи"},"es":{"title":"Encuentra dos formas"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'ambition' and t.version = 1
    and c.key = 'general' and p.key = 'find-way' and s.key = 'two-ways';
update public.stage_fields f set translations = '{"en":{"question":"How could this situation be made easier? Write down two different ideas.","help":"Think about what could be removed, simplified, prepared in advance or done for someone. The solution can be an object, a service, a program or a better way of organizing things.","example":"Collecting orders from nearby offices before making the sandwiches · Selling the leftover sandwiches in bundles at the end of the day"},"de":{"question":"Wie könnte man diese Situation leichter machen? Schreib zwei verschiedene Ideen auf.","help":"Überleg, was man weglassen, vereinfachen, vorab vorbereiten oder für jemanden erledigen könnte. Die Lösung kann ein Gegenstand, eine Dienstleistung, ein Programm oder eine bessere Organisation sein.","example":"Bestellungen aus nahen Büros sammeln, bevor die Sandwiches zubereitet werden · Übrig gebliebene Sandwiches am Ende des Tages im Paket verkaufen"},"uk":{"question":"Як можна полегшити цю ситуацію? Запиши дві різні ідеї.","help":"Подумай, що можна прибрати, спростити, підготувати заздалегідь або зробити за когось. Рішенням може бути річ, послуга, програма або кращий спосіб організації.","example":"Збирати замовлення з найближчих офісів до приготування сендвічів · Продавати залишки сендвічів наборами наприкінці дня"},"es":{"question":"¿Cómo se podría facilitar esta situación? Apunta dos ideas distintas.","help":"Piensa qué se puede quitar, simplificar, preparar de antemano o hacer por alguien. La solución puede ser un objeto, un servicio, un programa o una forma mejor de organizarse.","example":"Recoger pedidos de las oficinas cercanas antes de preparar los bocadillos · Vender los bocadillos sobrantes en packs al final del día"}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'ambition' and t.version = 1 and c.key = 'general' and p.key = 'find-way'
    and s.key = 'two-ways' and f.key = 'ideas';
update public.stage_subpoints s set translations = '{"en":{"title":"Pick the first direction"},"de":{"title":"Wähle eine erste Richtung"},"uk":{"title":"Вибери перший напрям"},"es":{"title":"Elige una primera dirección"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'ambition' and t.version = 1
    and c.key = 'general' and p.key = 'find-way' and s.key = 'pick-direction';
update public.stage_fields f set translations = '{"en":{"question":"Which of these ways do you want to check first?","help":"Pick the one whose workings you can imagine and that will be easiest for you to learn more about. Keep the other idea."},"de":{"question":"Welchen dieser Wege willst du zuerst prüfen?","help":"Wähle den, dessen Funktionsweise du dir vorstellen kannst und über den du am leichtesten mehr herausfinden kannst. Behalte die andere Idee."},"uk":{"question":"Який із цих способів ти хочеш перевірити першим?","help":"Вибери той, роботу якого ти можеш собі уявити й про який найлегше буде дізнатися більше. Іншу ідею збережи."},"es":{"question":"¿Cuál de estas formas quieres comprobar primero?","help":"Elige aquella cuyo funcionamiento puedas imaginar y sobre la que te resulte más fácil averiguar más. Guarda la otra idea."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'ambition' and t.version = 1 and c.key = 'general' and p.key = 'find-way'
    and s.key = 'pick-direction' and f.key = 'chosen_idea';
update public.stage_subpoints s set translations = '{"en":{"title":"Name the benefit"},"de":{"title":"Benenne den Nutzen"},"uk":{"title":"Назви користь"},"es":{"title":"Ponle nombre al beneficio"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'ambition' and t.version = 1
    and c.key = 'general' and p.key = 'find-way' and s.key = 'name-benefit';
update public.stage_fields f set translations = '{"en":{"question":"What will become easier or better for this person or company?","help":"Describe the change the recipient will notice. You don''t need numbers at this stage.","example":"The owner will sell more of the prepared food and throw less of it away."},"de":{"question":"Was wird für diese Person oder dieses Unternehmen leichter oder besser?","help":"Beschreib die Veränderung, die die Zielperson bemerken wird. In dieser Phase brauchst du keine Zahlen.","example":"Die Inhaberin verkauft mehr zubereitetes Essen und wirft weniger weg."},"uk":{"question":"Що стане легшим або кращим для цієї людини чи компанії?","help":"Опиши зміну, яку помітить отримувач. На цьому етапі цифри не потрібні.","example":"Власниця продасть більше приготованої їжі й менше викине."},"es":{"question":"¿Qué será más fácil o mejor para esta persona o empresa?","help":"Describe el cambio que notará quien lo reciba. En esta etapa no necesitas cifras.","example":"La dueña venderá más comida preparada y tirará menos."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'ambition' and t.version = 1 and c.key = 'general' and p.key = 'find-way'
    and s.key = 'name-benefit' and f.key = 'benefit';
update public.stage_points p set translations = '{"en":{"title":"Find your foothold","duration_hint":"About 2 minutes","guide_body":"Your advantage at the start isn''t experience in running a company, it''s access: you know someone, you work in the industry, you can do something yourself. That shortens the road to the first conversation with a recipient. Name the obstacle honestly — if you don''t see one, write “to be checked” and come back to it later."},"de":{"title":"Finde deinen Ansatzpunkt","duration_hint":"Etwa 2 Minuten","guide_body":"Dein Vorteil am Anfang ist nicht Erfahrung in der Unternehmensführung, sondern Zugang: Du kennst jemanden, arbeitest in der Branche oder kannst etwas selbst umsetzen. Das verkürzt den Weg zum ersten Gespräch mit der Zielgruppe. Nenne das Hindernis ehrlich — wenn du keins siehst, schreib „noch zu prüfen“ und komm später darauf zurück."},"uk":{"title":"Знайди свою точку опори","duration_hint":"Близько 2 хвилин","guide_body":"Перевага на старті — не досвід ведення бізнесу, а доступ: ти когось знаєш, працюєш у цій галузі, умієш щось зробити сам. Це скорочує шлях до першої розмови з клієнтом. Перешкоду назви чесно — якщо не бачиш її, напиши «треба перевірити» й повернися до цього пізніше."},"es":{"title":"Encuentra tu punto de partida","duration_hint":"Unos 2 minutos","guide_body":"Tu ventaja al empezar no es la experiencia dirigiendo una empresa, sino el acceso: conoces a alguien, trabajas en ese sector, sabes hacer algo por tu cuenta. Eso acorta el camino hasta la primera conversación con tu público. Señala el obstáculo con honestidad — si no lo ves, escribe «por comprobar» y vuelve a ello más tarde."}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'ambition' and t.version = 1
    and c.key = 'general' and p.key = 'foothold';
update public.stage_subpoints s set translations = '{"en":{"title":"Use what you already have"},"de":{"title":"Nutze, was du schon hast"},"uk":{"title":"Використай те, що вже маєш"},"es":{"title":"Aprovecha lo que ya tienes"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'ambition' and t.version = 1
    and c.key = 'general' and p.key = 'foothold' and s.key = 'use-what-you-have';
update public.stage_fields f set translations = '{"en":{"question":"What will help you start checking this idea? Write down up to three things.","help":"It can be knowing the problem, a skill, access to a place or a person you can talk to. You don''t need experience in running a company.","example":"I work at a café · I know its owner · I can make a simple order form"},"de":{"question":"Was hilft dir, mit der Prüfung dieser Idee anzufangen? Schreib höchstens drei Dinge auf.","help":"Das kann Wissen über das Problem sein, eine Fähigkeit, Zugang zu einem Ort oder eine Person, mit der du sprechen kannst. Du brauchst keine Erfahrung in der Unternehmensführung.","example":"Ich arbeite in einem Café · Ich kenne die Inhaberin · Ich kann ein einfaches Bestellformular erstellen"},"uk":{"question":"Що допоможе тобі почати перевіряти цю ідею? Запиши щонайбільше три речі.","help":"Це може бути знання проблеми, навичка, доступ до місця або людина, з якою можна поговорити. Досвід ведення бізнесу не потрібен.","example":"Працюю в кав''ярні · Знаю її власницю · Умію зробити просту форму замовлення"},"es":{"question":"¿Qué te ayudará a empezar a comprobar esta idea? Apunta como máximo tres cosas.","help":"Puede ser conocer el problema, una habilidad, acceso a un lugar o una persona con la que puedas hablar. No necesitas experiencia dirigiendo una empresa.","example":"Trabajo en una cafetería · Conozco a la dueña · Sé crear un formulario de pedidos sencillo"}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'ambition' and t.version = 1 and c.key = 'general' and p.key = 'foothold'
    and s.key = 'use-what-you-have' and f.key = 'assets';
update public.stage_subpoints s set translations = '{"en":{"title":"Notice the biggest obstacle"},"de":{"title":"Erkenne das größte Hindernis"},"uk":{"title":"Поміть найбільшу перешкоду"},"es":{"title":"Detecta el mayor obstáculo"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'ambition' and t.version = 1
    and c.key = 'general' and p.key = 'foothold' and s.key = 'biggest-obstacle';
update public.stage_fields f set translations = '{"en":{"question":"What makes it hardest for you to take the first step?","help":"Name one thing, e.g. no contact with recipients, little time or not knowing how the industry works. If you don''t see an obstacle yet, write “to be checked”."},"de":{"question":"Was erschwert dir den ersten Schritt am meisten?","help":"Nenne eine Sache, z. B. fehlender Kontakt zur Zielgruppe, wenig Zeit oder Unwissen darüber, wie die Branche funktioniert. Wenn du noch kein Hindernis siehst, schreib „noch zu prüfen“."},"uk":{"question":"Що найбільше заважає тобі зробити перший крок?","help":"Назви одну річ, напр. брак контакту з клієнтами, мало часу або незнання, як працює галузь. Якщо поки не бачиш перешкоди, напиши «треба перевірити»."},"es":{"question":"¿Qué es lo que más te dificulta dar el primer paso?","help":"Señala una sola cosa, p. ej. no tener contacto con tu público, poco tiempo o no saber cómo funciona el sector. Si todavía no ves ningún obstáculo, escribe «por comprobar»."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'ambition' and t.version = 1 and c.key = 'general' and p.key = 'foothold'
    and s.key = 'biggest-obstacle' and f.key = 'obstacle';
update public.stage_points p set translations = '{"en":{"title":"Save your idea","duration_hint":"About 1 minute","guide_body":"This is a summary of everything you''ve just written down. Read it as a whole and check that it reflects what you want to do. Fix only the answers that need it — the rest stays unchanged. Once you approve it, you move on to checking whether the people you want to help also need this change."},"de":{"title":"Halte deine Idee fest","duration_hint":"Etwa 1 Minute","guide_body":"Das ist die Zusammenfassung von allem, was du gerade aufgeschrieben hast. Lies sie als Ganzes und prüf, ob sie wiedergibt, was du vorhast. Korrigiere nur die Antworten, die es brauchen — der Rest bleibt unverändert. Nach der Bestätigung prüfst du, ob die Menschen, denen du helfen willst, eine solche Veränderung auch brauchen."},"uk":{"title":"Збережи свою ідею","duration_hint":"Близько 1 хвилини","guide_body":"Це підсумок усього, що щойно було записано. Прочитай його як одне ціле й перевір, чи він відображає те, що ти хочеш зробити. Виправ лише ті відповіді, які цього потребують — решта залишиться без змін. Після підтвердження ти перейдеш до перевірки, чи людям, яким хочеш допомогти, теж потрібна така зміна."},"es":{"title":"Guarda tu idea","duration_hint":"Alrededor de 1 minuto","guide_body":"Es el resumen de todo lo que acabas de escribir. Léelo como un todo y comprueba si refleja lo que quieres hacer. Corrige solo las respuestas que lo necesiten — el resto se queda igual. Tras confirmarlo, pasarás a comprobar si las personas a las que quieres ayudar también necesitan ese cambio."}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'ambition' and t.version = 1
    and c.key = 'general' and p.key = 'save-idea';
update public.stage_subpoints s set translations = '{"en":{"title":"Read the project outline"},"de":{"title":"Lies den Projektentwurf"},"uk":{"title":"Прочитай задум проєкту"},"es":{"title":"Lee el esbozo del proyecto"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'ambition' and t.version = 1
    and c.key = 'general' and p.key = 'save-idea' and s.key = 'project-outline';
update public.stage_fields f set translations = '{"en":{"question":"Check that the summary reflects what you want to do.","help":"You can fix any answer right here. Changes are saved in the same fields as before.","config":{"confirm_label":"I approve the outline","sources":[{"field":"pick-change.working-name.working_name","label":"Name"},{"field":"pick-change.who-to-help.audience","label":"I want to help"},{"field":"pick-change.catch-problem.problem","label":"The problem I''ll tackle"},{"field":"find-way.pick-direction.chosen_idea","label":"My idea for a solution"},{"field":"find-way.name-benefit.benefit","label":"Benefit for the recipient"},{"field":"foothold.use-what-you-have.assets","label":"What I have to start with"},{"field":"foothold.biggest-obstacle.obstacle","label":"To be clarified"}]}},"de":{"question":"Prüf, ob die Zusammenfassung wiedergibt, was du vorhast.","help":"Du kannst jede Antwort direkt hier korrigieren. Änderungen werden in denselben Feldern gespeichert wie zuvor.","config":{"confirm_label":"Entwurf bestätigen","sources":[{"field":"pick-change.working-name.working_name","label":"Name"},{"field":"pick-change.who-to-help.audience","label":"Ich will helfen"},{"field":"pick-change.catch-problem.problem","label":"Problem, das ich angehe"},{"field":"find-way.pick-direction.chosen_idea","label":"Meine Lösungsidee"},{"field":"find-way.name-benefit.benefit","label":"Nutzen für die Zielgruppe"},{"field":"foothold.use-what-you-have.assets","label":"Was ich zum Start habe"},{"field":"foothold.biggest-obstacle.obstacle","label":"Noch zu klären"}]}},"uk":{"question":"Перевір, чи підсумок відображає те, що ти хочеш зробити.","help":"Будь-яку відповідь можна виправити тут же. Зміни зберігаються в тих самих полях, що й раніше.","config":{"confirm_label":"Підтверджую задум","sources":[{"field":"pick-change.working-name.working_name","label":"Назва"},{"field":"pick-change.who-to-help.audience","label":"Хочу допомогти"},{"field":"pick-change.catch-problem.problem","label":"Проблема, якою займуся"},{"field":"find-way.pick-direction.chosen_idea","label":"Моя ідея рішення"},{"field":"find-way.name-benefit.benefit","label":"Користь для отримувача"},{"field":"foothold.use-what-you-have.assets","label":"Що маю на початок"},{"field":"foothold.biggest-obstacle.obstacle","label":"Треба з''ясувати"}]}},"es":{"question":"Comprueba si el resumen refleja lo que quieres hacer.","help":"Puedes corregir cualquier respuesta aquí mismo. Los cambios se guardan en los mismos campos que antes.","config":{"confirm_label":"Confirmo el esbozo","sources":[{"field":"pick-change.working-name.working_name","label":"Nombre"},{"field":"pick-change.who-to-help.audience","label":"Quiero ayudar a"},{"field":"pick-change.catch-problem.problem","label":"El problema que voy a abordar"},{"field":"find-way.pick-direction.chosen_idea","label":"Mi idea de solución"},{"field":"find-way.name-benefit.benefit","label":"Beneficio para el destinatario"},{"field":"foothold.use-what-you-have.assets","label":"Con qué cuento para empezar"},{"field":"foothold.biggest-obstacle.obstacle","label":"Por aclarar"}]}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'ambition' and t.version = 1 and c.key = 'general' and p.key = 'save-idea'
    and s.key = 'project-outline' and f.key = 'outline';

-- ═══ idea v1 ═══
update public.stage_templates t set translations = '{"en":{"title":"Idea Stage","subtitle":"Check whether the idea makes sense","intro":"Reduce uncertainty and find the gaps in your own idea. Check who your idea can help, what problem it solves for those people and whether it can make money.","finish_label":"I''m finishing the idea validation"},"de":{"title":"Idea Stage","subtitle":"Prüfe, ob die Idee Sinn ergibt","intro":"Verringere Unsicherheiten und finde Lücken in deiner eigenen Idee. Prüfe, wem deine Idee helfen kann, welches Problem sie für diese Menschen löst und ob sich damit Geld verdienen lässt.","finish_label":"Ich schließe die Validierung der Idee ab"},"uk":{"title":"Idea Stage","subtitle":"Перевір, чи має ідея сенс","intro":"Зменш невизначеність і знайди прогалини у власній ідеї. Перевір, кому твоя ідея може допомогти, яку проблему вона розв’язує для цих людей і чи можна на ній заробляти.","finish_label":"Завершую валідацію ідеї"},"es":{"title":"Idea Stage","subtitle":"Comprueba si la idea tiene sentido","intro":"Reduce la incertidumbre y detecta huecos en tu propia idea. Comprueba a quién puede ayudar tu idea, qué problema resuelve a esas personas y si se puede ganar dinero con ella.","finish_label":"Termino la validación de la idea"}}'::jsonb
  where t.key = 'idea' and t.version = 1;
update public.stage_categories c set translations = '{"en":{"title":"General validation","intro":"The foundation for every idea, no matter what you''re building or who you''re selling to."},"de":{"title":"Allgemeine Validierung","intro":"Die Grundlage für jede Idee, unabhängig davon, was du baust und an wen du verkaufst."},"uk":{"title":"Загальна валідація","intro":"Основа для будь-якої ідеї, незалежно від того, що ти будуєш і кому продаєш."},"es":{"title":"Validación general","intro":"La base para cualquier idea, independientemente de lo que construyas y a quién vendas."}}'::jsonb
  from public.stage_templates t where c.template_id = t.id and t.key = 'idea' and t.version = 1 and c.key = 'general';
update public.stage_points p set translations = '{"en":{"title":"Define the problem","guide_body":"Describe a specific situation\nStart with what causes someone difficulty. “People waste time” is too broad. “A shop owner compares several files every Friday to work out what to order” already lets you picture the situation and find a person to talk to.\nIn the problem field, describe what this person wants to do, when they try to do it and what gets in their way. If you see the word “case” in the form, it means exactly such a specific instance. Avoid writing “no app”, because that imposes the solution in advance. The obstacle can be, for example, scattered information, difficulty finding help or a complicated task.\nIf you''re relying on your own experience, give an example. If you don''t know something yet, mark it “assumption” or “to be checked”. Don''t make up data to fill in a field.\nName the person and how they work today\nPick a group whose members can be recognized by traits related to the problem. Instead of “entrepreneurs” you can write “owners of small online shops who order stock themselves”. Add age, gender or city only when they matter for the difficulty you''re describing.\nThen describe how such a person copes today. They may use a program, keep notes, hire help or put up with the inconvenience. If they do nothing, it''s worth asking later why. Doing nothing can mean a small need, but also a lack of time, money or an available way to get help.\nSeparate the obstacle from its effects\nThe obstacle is, e.g., having to compare three separate files. The effect is the time spent on it or a mistake in the order. Write down both, so you know what you want to improve and why anyone would care about it.\nGive numbers when you have grounds to use them: “according to the interviewee, about an hour a week”. If you only suspect that mistakes cause losses, write it down as a question to check. Don''t present possible consequences as something that has already been observed.\nRate importance and urgency\nThe 1–5 slider helps organize your current assessment. You can take 1 to mean a minor inconvenience, 3 a clear difficulty and 5 serious consequences or a blocked important task. Ratings 2 and 4 are in between. That''s the working meaning of the scale in this exercise, with no threshold that passes the idea.\nUrgency answers a different question: how quickly does something need to be done about it? A problem can be painful but only appear in a few months. On the need-for-a-solution slider, consider whether the person can calmly wait or has to act now. Later compare your own rating with examples from the interviews. A high rating alone doesn''t prove readiness to buy.\nBuild the problem statement from five fields\nFill in, in order: who, what they''re trying to do, in what situation, what gets in the way and what the effect is. You''ll get a sentence following the pattern: “[Who] are trying to [do what] [in what situation], but [obstacle], so [effect]”. Fix the wording if the automatically assembled text sounds clumsy.\nExample: “Owners of small online shops are trying to work out what to order during their weekly restocking, but the data is scattered across several files, so comparing the information by hand takes them a lot of time”.\nAfter this point you have a problem description, a specific recipient and an initial assessment of how much the difficulty matters. The “final definition” in the form is a summary for now. You can improve it after the interviews.","guide_sources":["Paul Graham, How to Get Startup Ideas. Basis: looking for the problems of specific recipients and recognizing a strong need.","Paul Graham, Before the Startup. Basis: getting to know users and their problems at the start of the work."]},"de":{"title":"Definiere das Problem","guide_body":"Beschreibe eine konkrete Situation\nFang damit an, was jemandem Schwierigkeiten bereitet. „Menschen verlieren Zeit“ ist zu breit. „Die Inhaberin eines Ladens vergleicht jeden Freitag mehrere Dateien, um festzulegen, was bestellt werden soll“ lässt sich schon vorstellen und hilft, eine Person für ein Gespräch zu finden.\nBeschreibe im Feld zum Problem, was diese Person tun will, wann sie es versucht und was sie daran hindert. Wenn du im Formular das Wort „Case“ siehst, ist genau so ein konkreter Fall gemeint. Schreib nicht „fehlende App“, denn das gibt die Lösung schon vor. Das Hindernis können zum Beispiel verstreute Informationen sein, die Schwierigkeit, Hilfe zu finden, oder ein komplizierter Ablauf.\nWenn du dich auf eigene Erfahrung stützt, nenne ein Beispiel. Wenn du etwas noch nicht weißt, markiere es als „Vermutung“ oder „zu prüfen“. Erfinde keine Daten, um ein Feld zu füllen.\nNenne die Person und ihre heutige Vorgehensweise\nWähle eine Gruppe, deren Mitglieder sich an Merkmalen erkennen lassen, die mit dem Problem zu tun haben. Statt „Unternehmer“ kannst du „Inhaber kleiner Onlineshops, die ihre Ware selbst bestellen“ schreiben. Alter, Geschlecht oder Stadt ergänzt du nur, wenn sie für die beschriebene Schwierigkeit wichtig sind.\nBeschreibe dann, wie diese Person heute zurechtkommt. Sie kann ein Programm nutzen, Notizen führen, Hilfe bezahlen oder die Unannehmlichkeit hinnehmen. Wenn sie nichts tut, lohnt es sich später zu fragen, warum. Untätigkeit kann ein geringes Bedürfnis bedeuten, aber auch fehlende Zeit, fehlendes Geld oder keinen verfügbaren Weg, Hilfe zu bekommen.\nTrenne das Hindernis von seinen Folgen\nDas Hindernis ist z. B., drei getrennte Dateien vergleichen zu müssen. Die Folge ist die dafür aufgewendete Zeit oder ein Fehler in der Bestellung. Schreib beides auf, damit du weißt, was du verbessern willst und warum es jemandem wichtig sein sollte.\nNenne Zahlen, wenn du eine Grundlage dafür hast: „laut Gesprächspartner etwa eine Stunde pro Woche“. Wenn du nur vermutest, dass Fehler Verluste verursachen, schreib es als Frage zum Prüfen auf. Stelle mögliche Folgen nicht als etwas dar, das bereits beobachtet wurde.\nBewerte Wichtigkeit und Dringlichkeit\nDer Regler 1–5 hilft, deine aktuelle Einschätzung zu ordnen. Du kannst annehmen, dass 1 eine kleine Unannehmlichkeit bedeutet, 3 eine deutliche Erschwernis und 5 ernste Folgen oder eine blockierte wichtige Aufgabe. 2 und 4 liegen dazwischen. So ist die Skala in dieser Übung gemeint — ohne Schwelle, ab der eine Idee „bestanden“ hat.\nDie Dringlichkeit beantwortet eine andere Frage: Wie schnell muss etwas dagegen getan werden? Ein Problem kann schmerzhaft sein, aber erst in einigen Monaten auftreten. Überlege beim Regler für den Lösungsbedarf, ob die Person in Ruhe warten kann oder jetzt handeln muss. Vergleiche deine Einschätzung später mit Beispielen aus den Gesprächen. Eine hohe Bewertung allein beweist keine Kaufbereitschaft.\nSetze die Problembeschreibung aus fünf Feldern zusammen\nFülle nacheinander aus: wer, was versucht wird, in welcher Situation, was im Weg steht und was die Folge ist. Du erhältst einen Satz nach dem Muster: „[Wer] versucht, [was zu tun] [in welcher Situation], aber [Hindernis], wodurch [Folge]“. Korrigiere Wortendungen, wenn der automatisch zusammengesetzte Text holprig klingt.\nBeispiel: „Inhaber kleiner Onlineshops versuchen beim wöchentlichen Auffüllen des Lagers festzulegen, was sie bestellen sollen, aber die Daten liegen verstreut in mehreren Dateien, wodurch der manuelle Vergleich viel Zeit kostet.“\nNach diesem Punkt hast du eine Problembeschreibung, einen konkreten Empfänger und eine erste Einschätzung, wie wichtig die Schwierigkeit ist. Die „endgültige Definition“ im Formular ist eine Zusammenfassung für jetzt. Du kannst sie nach den Gesprächen verbessern.","guide_sources":["Paul Graham, How to Get Startup Ideas. Grundlage: nach Problemen konkreter Zielgruppen suchen und ein starkes Bedürfnis erkennen.","Paul Graham, Before the Startup. Grundlage: Nutzer und ihre Probleme zu Beginn der Arbeit kennenlernen."]},"uk":{"title":"Визнач проблему","guide_body":"Опиши конкретну ситуацію\nПочни з того, що комусь завдає труднощів. «Люди втрачають час» — надто широко. «Власниця магазину щоп’ятниці порівнює кілька файлів, щоб вирішити, що замовити» вже дає змогу уявити ситуацію й знайти людину для розмови.\nУ полі про проблему опиши, що ця людина хоче зробити, коли вона намагається це зробити і що їй заважає. Якщо у формі бачиш слово «кейс», ідеться саме про такий конкретний випадок. Не пиши «немає застосунку», бо це наперед нав’язує рішення. Перешкодою можуть бути, наприклад, розпорошена інформація, складність у пошуку допомоги чи заплутана дія.\nЯкщо спираєшся на власний досвід, наведи приклад. Якщо чогось ще не знаєш, познач «припущення» або «перевірити». Не вигадуй даних, щоб заповнити поле.\nВкажи людину та її теперішній спосіб дій\nОбери групу, членів якої можна впізнати за ознаками, пов’язаними з проблемою. Замість «підприємці» можеш написати «власники невеликих інтернет-магазинів, які самі замовляють товар». Вік, стать чи місто додавай лише тоді, коли вони важливі для описаної труднощі.\nДалі опиши, як така людина дає собі раду сьогодні. Вона може користуватися програмою, вести нотатки, наймати допомогу або миритися з незручністю. Якщо вона нічого не робить, варто пізніше запитати чому. Бездіяльність може означати слабку потребу, але також брак часу, грошей чи доступного способу допомоги.\nВідокрем перешкоду від її наслідків\nПерешкода — це, наприклад, потреба порівнювати три окремі файли. Наслідок — час, витрачений на це, або помилка в замовленні. Запиши обидва елементи, щоб знати, що ти хочеш покращити і чому це має комусь бути важливим.\nНаводь цифри, коли маєш для них підставу: «за словами співрозмовника, приблизно година на тиждень». Якщо ти лише підозрюєш, що помилки спричиняють втрати, запиши це як запитання для перевірки. Не подавай можливі наслідки як щось, що вже вдалося спостерегти.\nОціни важливість і терміновість\nПовзунок 1–5 допомагає впорядкувати твою поточну оцінку. Можна вважати, що 1 — це дрібна незручність, 3 — відчутна перешкода, а 5 — серйозні наслідки або заблоковане важливе завдання. 2 і 4 — проміжні. Це робоче значення шкали в цій вправі, без порогу, з якого ідея «зараховується».\nТерміновість відповідає на інше запитання: як швидко з цим треба щось робити? Проблема може бути болючою, але з’являтися лише за кілька місяців. Біля повзунка потреби в рішенні подумай, чи людина може спокійно почекати, чи мусить діяти зараз. Пізніше порівняй власну оцінку з прикладами з розмов. Висока оцінка сама не доводить готовності купити.\nСклади опис проблеми з п’яти полів\nЗаповни по черзі: хто, що намагається зробити, у якій ситуації, що заважає і який наслідок. Ти отримаєш речення за зразком: «[Хто] намагаються [що зробити] [у якій ситуації], але [перешкода], через що [наслідок]». Виправ закінчення слів, якщо автоматично складений текст звучить незграбно.\nПриклад: «Власники невеликих інтернет-магазинів намагаються визначити, що замовити під час щотижневого поповнення запасів, але дані розкидані по кількох файлах, через що ручне порівняння інформації забирає їм багато часу».\nПісля цього пункту в тебе є опис проблеми, конкретний адресат і попередня оцінка того, наскільки важлива ця трудність. «Остаточне визначення» у формі — це підсумок на зараз. Його можна виправити після розмов.","guide_sources":["Paul Graham, How to Get Startup Ideas. Основа: пошук проблем конкретних адресатів і розпізнавання сильної потреби.","Paul Graham, Before the Startup. Основа: знайомство з користувачами та їхніми проблемами на початку роботи."]},"es":{"title":"Define el problema","guide_body":"Describe una situación concreta\nEmpieza por lo que le cuesta a alguien. «La gente pierde tiempo» es demasiado amplio. «La dueña de una tienda compara cada viernes varios archivos para decidir qué pedir» ya permite imaginar la situación y encontrar a alguien con quien hablar.\nEn el campo del problema, describe qué quiere hacer esa persona, cuándo lo intenta y qué se lo impide. Si en el formulario ves la palabra «caso», se refiere justo a un caso concreto así. Evita escribir «falta una app», porque impone la solución de antemano. El obstáculo puede ser, por ejemplo, información dispersa, dificultad para encontrar ayuda o una tarea complicada.\nSi te basas en tu propia experiencia, da un ejemplo. Si todavía no sabes algo, márcalo como «suposición» o «por comprobar». No inventes datos para rellenar el campo.\nIndica la persona y cómo actúa hoy\nElige un grupo cuyos miembros se puedan reconocer por rasgos relacionados con el problema. En lugar de «emprendedores» puedes escribir «dueños de pequeñas tiendas online que hacen ellos mismos los pedidos de mercancía». Añade edad, sexo o ciudad solo si importan para la dificultad que describes.\nDespués describe cómo se las arregla esa persona hoy. Puede usar un programa, tomar notas, pagar ayuda o aceptar la incomodidad. Si no hace nada, conviene preguntar más adelante por qué. No actuar puede significar una necesidad pequeña, pero también falta de tiempo, de dinero o de una forma accesible de obtener ayuda.\nSepara el obstáculo de sus consecuencias\nEl obstáculo es, por ejemplo, tener que comparar tres archivos distintos. La consecuencia es el tiempo dedicado a ello o un error en el pedido. Anota ambos para saber qué quieres mejorar y por qué a alguien debería importarle.\nDa cifras cuando tengas base para usarlas: «según la persona entrevistada, una hora a la semana más o menos». Si solo sospechas que los errores causan pérdidas, anótalo como pregunta por comprobar. No presentes consecuencias posibles como algo que ya se ha observado.\nValora la importancia y la urgencia\nEl control 1–5 ayuda a ordenar tu valoración actual. Puedes considerar que 1 es una pequeña molestia, 3 una dificultad clara y 5 consecuencias graves o una tarea importante bloqueada. 2 y 4 son intermedios. Es el sentido práctico de la escala en este ejercicio, sin un umbral que «apruebe» la idea.\nLa urgencia responde a otra pregunta: ¿con qué rapidez hay que hacer algo al respecto? Un problema puede ser doloroso, pero aparecer solo dentro de unos meses. En el control de necesidad de solución, piensa si la persona puede esperar tranquila o tiene que actuar ya. Más adelante compara tu valoración con ejemplos de las conversaciones. Una nota alta por sí sola no demuestra disposición a comprar.\nMonta la descripción del problema con cinco campos\nRellena por orden: quién, qué intenta hacer, en qué situación, qué se lo impide y cuál es la consecuencia. Obtendrás una frase con el patrón: «[Quién] intenta [qué hacer] [en qué situación], pero [obstáculo], por lo que [consecuencia]». Corrige las terminaciones si el texto montado automáticamente suena torpe.\nEjemplo: «Los dueños de pequeñas tiendas online intentan decidir qué pedir al reponer existencias cada semana, pero los datos están repartidos en varios archivos, por lo que comparar la información a mano les lleva mucho tiempo».\nTras este punto tienes una descripción del problema, un destinatario concreto y una valoración inicial de la importancia de la dificultad. La «definición final» del formulario es un resumen para ahora. Puedes mejorarla después de las conversaciones.","guide_sources":["Paul Graham, How to Get Startup Ideas. Base: buscar problemas de destinatarios concretos y reconocer una necesidad fuerte.","Paul Graham, Before the Startup. Base: conocer a los usuarios y sus problemas al principio del trabajo."]}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'idea' and t.version = 1
    and c.key = 'general' and p.key = 'zdefiniuj-problem';
update public.stage_subpoints s set translations = '{"en":{"title":"Describe the problem and where it occurs"},"de":{"title":"Beschreibe das Problem und wo es auftritt"},"uk":{"title":"Опиши проблему і де вона виникає"},"es":{"title":"Describe el problema y dónde ocurre"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'idea' and t.version = 1
    and c.key = 'general' and p.key = 'zdefiniuj-problem' and s.key = 'opisz-problem';
update public.stage_fields f set translations = '{"en":{"question":"What currently doesn''t work, who does this problem affect and why?","help":"The more specific, the better. “People waste time” is too broad — describe a specific person and a specific situation."},"de":{"question":"Was funktioniert gerade nicht, wen betrifft das Problem und warum?","help":"Je konkreter, desto besser. „Menschen verlieren Zeit“ ist zu breit — beschreibe eine konkrete Person und eine konkrete Situation."},"uk":{"question":"Що зараз не працює, кого стосується проблема і чому?","help":"Що конкретніше, то краще. «Люди втрачають час» — надто широко: опиши конкретну людину й конкретну ситуацію."},"es":{"question":"¿Qué no funciona ahora, a quién afecta el problema y por qué?","help":"Cuanto más concreto, mejor. «La gente pierde tiempo» es demasiado amplio: describe una persona concreta y una situación concreta."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'idea' and t.version = 1 and c.key = 'general' and p.key = 'zdefiniuj-problem'
    and s.key = 'opisz-problem' and f.key = 'co-nie-dziala';
update public.stage_fields f set translations = '{"en":{"question":"Describe the specific situation, moment and context in which the problem occurs.","help":"When exactly does it happen? Once a week, with every order, at the end of the month?"},"de":{"question":"Beschreibe die konkrete Situation, den Moment und den Kontext, in dem das Problem auftritt.","help":"Wann genau passiert das? Einmal pro Woche, bei jeder Bestellung, am Monatsende?"},"uk":{"question":"Опиши конкретну ситуацію, момент і контекст, у якому виникає проблема.","help":"Коли саме це трапляється? Раз на тиждень, під час кожного замовлення, наприкінці місяця?"},"es":{"question":"Describe la situación concreta, el momento y el contexto en que aparece el problema.","help":"¿Cuándo pasa exactamente? ¿Una vez a la semana, con cada pedido, a final de mes?"}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'idea' and t.version = 1 and c.key = 'general' and p.key = 'zdefiniuj-problem'
    and s.key = 'opisz-problem' and f.key = 'sytuacja';
update public.stage_subpoints s set translations = '{"en":{"title":"Example user"},"de":{"title":"Beispielhafte Nutzerin oder Nutzer"},"uk":{"title":"Приклад користувача"},"es":{"title":"Usuario de ejemplo"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'idea' and t.version = 1
    and c.key = 'general' and p.key = 'zdefiniuj-problem' and s.key = 'przykladowy-uzytkownik';
update public.stage_fields f set translations = '{"en":{"question":"Describe the person or organization the problem affects.","help":"Role, situation, industry — whatever matters for your idea. Instead of “entrepreneurs” write “owners of small online shops”."},"de":{"question":"Beschreibe die Person oder Organisation, die das Problem betrifft.","help":"Rolle, Situation, Branche — was für deine Idee wichtig ist. Statt „Unternehmer“ schreib „Inhaber kleiner Onlineshops“."},"uk":{"question":"Опиши людину чи організацію, якої стосується проблема.","help":"Роль, ситуація, галузь — те, що важливо для твоєї ідеї. Замість «підприємці» напиши «власники невеликих інтернет-магазинів»."},"es":{"question":"Describe a la persona u organización a la que afecta el problema.","help":"Rol, situación, sector: lo que importa para tu idea. En lugar de «emprendedores», escribe «dueños de pequeñas tiendas online»."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'idea' and t.version = 1 and c.key = 'general' and p.key = 'zdefiniuj-problem'
    and s.key = 'przykladowy-uzytkownik' and f.key = 'kto';
update public.stage_fields f set translations = '{"en":{"question":"How does this person deal with the problem today?","help":"What products, services, processes, workarounds or manual solutions do they use? If they do nothing — that''s an answer too."},"de":{"question":"Wie kommt diese Person heute mit dem Problem zurecht?","help":"Welche Produkte, Dienste, Abläufe, Umwege oder manuellen Lösungen nutzt sie? Wenn sie nichts tut — ist das auch eine Antwort."},"uk":{"question":"Як ця людина дає раду з проблемою сьогодні?","help":"Які продукти, послуги, процеси, обхідні шляхи чи ручні рішення вона використовує? Якщо нічого не робить — це теж відповідь."},"es":{"question":"¿Cómo se las arregla hoy esa persona con el problema?","help":"¿Qué productos, servicios, procesos, atajos o soluciones manuales usa? Si no hace nada, eso también es una respuesta."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'idea' and t.version = 1 and c.key = 'general' and p.key = 'zdefiniuj-problem'
    and s.key = 'przykladowy-uzytkownik' and f.key = 'jak-radzi-sobie-dzis';
update public.stage_subpoints s set translations = '{"en":{"title":"Where the current solution fails"},"de":{"title":"Wo die heutige Lösung nicht funktioniert"},"uk":{"title":"Де нинішнє рішення не працює"},"es":{"title":"Dónde falla la solución actual"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'idea' and t.version = 1
    and c.key = 'general' and p.key = 'zdefiniuj-problem' and s.key = 'gdzie-nie-dziala';
update public.stage_fields f set translations = '{"en":{"question":"Name the specific problems with the current way of doing things.","help":"Wasted time, costs, mistakes, frustration, inconvenience. Give numbers when you have grounds: “according to the interviewee, about an hour a week”."},"de":{"question":"Nenne konkrete Probleme der heutigen Vorgehensweise.","help":"Zeitverlust, Kosten, Fehler, Frust, fehlender Komfort. Nenne Zahlen, wenn du eine Grundlage hast: „laut Gesprächspartner etwa eine Stunde pro Woche“."},"uk":{"question":"Вкажи конкретні проблеми теперішнього способу дій.","help":"Втрата часу, витрати, помилки, роздратування, незручність. Наводь цифри, коли маєш підставу: «за словами співрозмовника, приблизно година на тиждень»."},"es":{"question":"Señala problemas concretos de la forma actual de actuar.","help":"Pérdida de tiempo, costes, errores, frustración, incomodidad. Da cifras cuando tengas base: «según la persona entrevistada, una hora a la semana más o menos»."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'idea' and t.version = 1 and c.key = 'general' and p.key = 'zdefiniuj-problem'
    and s.key = 'gdzie-nie-dziala' and f.key = 'problemy';
update public.stage_fields f set translations = '{"en":{"question":"What consequences follow from it?","help":"Lost revenue, risk, wasted resources, missed opportunities. Separate the obstacle itself from its effects."},"de":{"question":"Welche Folgen hat das?","help":"Entgangene Einnahmen, Risiko, verschwendete Ressourcen, verpasste Chancen. Trenne das Hindernis selbst von seinen Folgen."},"uk":{"question":"Які це має наслідки?","help":"Втрачені доходи, ризик, змарновані ресурси, упущені можливості. Відокрем саму перешкоду від її наслідків."},"es":{"question":"¿Qué consecuencias tiene?","help":"Ingresos perdidos, riesgo, recursos desperdiciados, oportunidades perdidas. Separa el obstáculo en sí de sus consecuencias."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'idea' and t.version = 1 and c.key = 'general' and p.key = 'zdefiniuj-problem'
    and s.key = 'gdzie-nie-dziala' and f.key = 'konsekwencje';
update public.stage_subpoints s set translations = '{"en":{"title":"How important this problem is"},"de":{"title":"Wie wichtig dieses Problem ist"},"uk":{"title":"Наскільки важлива ця проблема"},"es":{"title":"Lo importante que es este problema"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
