update public.stage_subpoints s set translations = '{"en":{"title":"Define the help needed"},"de":{"title":"Lege die nötige Hilfe fest"},"uk":{"title":"Визнач потрібну допомогу"},"es":{"title":"Define la ayuda necesaria"}}'::jsonb
