update public.stage_fields f set translations = '{"en":{"question":"What help might the customer need later?","help":"E.g. when changing settings, data or the way of working."},"de":{"question":"Welche Hilfe könnten Kunden später brauchen?","help":"Z. B. bei geänderten Einstellungen, Daten oder Arbeitsweisen."},"uk":{"question":"Якої допомоги клієнт може потребувати пізніше?","help":"Напр. при зміні налаштувань, даних або способу роботи."},"es":{"question":"¿Qué ayuda puede necesitar el cliente más adelante?","help":"P. ej. al cambiar ajustes, datos o la forma de trabajar."}}'::jsonb
