update public.stage_fields f set translations = '{"en":{"question":"Describe the ideal customer profile — the company.","help":"Industry, size, number of employees, way of working, technological maturity. The narrower, the easier it is to find."},"de":{"question":"Beschreibe das Profil des idealen Kunden — der Firma.","help":"Branche, Größe, Zahl der Beschäftigten, Arbeitsweise, technologische Reife. Je enger, desto leichter zu finden."},"uk":{"question":"Опиши профіль ідеального клієнта — компанії.","help":"Галузь, розмір, кількість працівників, спосіб роботи, технологічна зрілість. Що вужче, то легше її знайти."},"es":{"question":"Describe el perfil del cliente ideal: la empresa.","help":"Sector, tamaño, número de empleados, forma de trabajar, madurez tecnológica. Cuanto más concreto, más fácil encontrarla."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'idea' and t.version = 1 and c.key = 'b2b' and p.key = 'decyzja-o-zakupie'
    and s.key = 'docelowa-firma' and f.key = 'profil-firmy';
update public.stage_fields f set translations = '{"en":{"question":"Describe the person who will use your solution.","help":"Role, situation, industry — whatever matters for your idea. If the answer was already given in General validation, you''ll see your answer here."},"de":{"question":"Beschreibe die Person, die deine Lösung nutzen wird.","help":"Rolle, Situation, Branche — was für deine Idee zählt. Wenn die Antwort schon in der Allgemeinen Validierung gegeben wurde, siehst du sie hier."},"uk":{"question":"Опиши людину, яка користуватиметься твоїм рішенням.","help":"Роль, ситуація, галузь — те, що важливо для твоєї ідеї. Якщо відповідь уже була в Загальній валідації, ти побачиш її тут."},"es":{"question":"Describe a la persona que usará tu solución.","help":"Función, situación, sector: lo que importa para tu idea. Si ya respondiste en la Validación general, verás aquí tu respuesta."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'idea' and t.version = 1 and c.key = 'b2b' and p.key = 'decyzja-o-zakupie'
    and s.key = 'docelowa-firma' and f.key = 'profil-uzytkownika';
update public.stage_subpoints s set translations = '{"en":{"title":"Who decides on the purchase"},"de":{"title":"Wer über den Kauf entscheidet"},"uk":{"title":"Хто вирішує про покупку"},"es":{"title":"Quién decide la compra"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
