update public.stage_fields f set translations = '{"en":{"question":"Who has the problem, who controls the budget, who signs the contract, and who can block the purchase?","help":"Write one role per item. Often these are four different people — and each needs a different argument."},"de":{"question":"Wer hat das Problem, wer verfügt über das Budget, wer unterschreibt den Vertrag und wer kann den Kauf blockieren?","help":"Trag eine Rolle pro Zeile ein. Oft sind es vier verschiedene Personen — und jede braucht ein anderes Argument."},"uk":{"question":"Хто має проблему, хто розпоряджається бюджетом, хто підписує договір, а хто може заблокувати покупку?","help":"Одна роль на позицію. Часто це чотири різні людини — і кожній потрібен інший аргумент."},"es":{"question":"¿Quién tiene el problema, quién maneja el presupuesto, quién firma el contrato y quién puede bloquear la compra?","help":"Una función por línea. A menudo son cuatro personas distintas, y cada una necesita un argumento diferente."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'idea' and t.version = 1 and c.key = 'b2b' and p.key = 'decyzja-o-zakupie'
    and s.key = 'kto-decyduje' and f.key = 'role';
update public.stage_subpoints s set translations = '{"en":{"title":"Check the approvals required"},"de":{"title":"Prüfe die nötigen Zustimmungen"},"uk":{"title":"Перевір потрібні погодження"},"es":{"title":"Comprueba las aprobaciones necesarias"}}'::jsonb
