update public.stage_fields f set translations = '{"en":{"question":"Which departments do you have to reach?","help":"E.g. IT, legal, security, finance. Each of them can hold up a purchase for weeks."},"de":{"question":"Welche Abteilungen musst du erreichen?","help":"Z. B. IT, Recht, Sicherheit, Finanzen. Jede davon kann einen Kauf wochenlang aufhalten."},"uk":{"question":"До яких відділів тобі треба дістатися?","help":"Напр. IT, юридичний, безпека, фінанси. Кожен із них може зупинити покупку на тижні."},"es":{"question":"¿A qué departamentos tienes que llegar?","help":"P. ej. IT, legal, seguridad, finanzas. Cualquiera puede frenar una compra durante semanas."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
