update public.stage_fields f set translations = '{"en":{"question":"Is one person''s decision enough, or is approval from several needed?"},"de":{"question":"Reicht die Entscheidung einer Person oder braucht es die Zustimmung mehrerer?"},"uk":{"question":"Чи досить рішення однієї людини, чи потрібна згода кількох?"},"es":{"question":"¿Basta con la decisión de una persona o hace falta el visto bueno de varias?"}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'idea' and t.version = 1 and c.key = 'b2b' and p.key = 'czas-sprzedazy'
    and s.key = 'jak-decyduje' and f.key = 'ile-osob';
update public.stage_fields f set translations = '{"en":{"question":"Can the company buy such a solution at any time, or does it have to plan the money for it in advance?","help":"A planned budget means the sale may have to wait until next year."},"de":{"question":"Kann die Firma eine solche Lösung jederzeit kaufen oder muss sie vorher Geld dafür einplanen?","help":"Ein eingeplantes Budget bedeutet, dass der Verkauf bis zum nächsten Jahr warten kann."},"uk":{"question":"Чи може компанія купити таке рішення будь-коли, чи мусить заздалегідь запланувати на нього гроші?","help":"Запланований бюджет означає, що продаж може чекати до наступного року."},"es":{"question":"¿Puede la empresa comprar esa solución en cualquier momento o tiene que planificar antes el dinero?","help":"Un presupuesto planificado significa que la venta puede esperar al año siguiente."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'idea' and t.version = 1 and c.key = 'b2b' and p.key = 'czas-sprzedazy'
    and s.key = 'jak-decyduje' and f.key = 'budzet';
update public.stage_subpoints s set translations = '{"en":{"title":"Identify the biggest delays"},"de":{"title":"Finde die größten Verzögerungen"},"uk":{"title":"Визнач найбільші затримки"},"es":{"title":"Identifica los mayores retrasos"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'idea' and t.version = 1
