update public.stage_fields f set translations = '{"en":{"question":"Who chooses?","help":"e.g. the student together with a parent"},"de":{"question":"Wer wählt aus?","help":"z. B. der Schüler zusammen mit einem Elternteil"},"uk":{"question":"Хто обирає?","help":"напр. учень разом із батьками"},"es":{"question":"¿Quién elige?","help":"p. ej. el alumno junto con su madre o padre"}}'::jsonb
