    and s.key = 'okazja-zakupu' and f.key = 'sytuacja';
update public.stage_subpoints s set translations = '{"en":{"title":"Place the expense in the private budget","description":"Specify where in the private budget the money is to come from and whether the purchase replaces an existing expense."},"de":{"title":"Ordne die Ausgabe ins private Budget ein","description":"Lege fest, woher im privaten Budget das Geld kommen soll und ob der Kauf eine bisherige Ausgabe ersetzt."},"uk":{"title":"Впиши витрату в приватний бюджет","description":"Визнач, звідки в приватному бюджеті мають узятися гроші і чи покупка замінює дотеперішню витрату."},"es":{"title":"Sitúa el gasto en el presupuesto personal","description":"Indica de qué parte del presupuesto personal saldrá el dinero y si la compra sustituye un gasto actual."}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'idea' and t.version = 1
