update public.stage_fields f set translations = '{"en":{"question":"I''ve put out a short piece of information about the product in the chosen places.","help":"You don''t need a product — a description of what you intend to make is enough."},"de":{"question":"Eine kurze Info zum Produkt ist an den gewählten Orten veröffentlicht.","help":"Du brauchst kein Produkt — eine Beschreibung dessen, was du vorhast, reicht."},"uk":{"question":"Коротку інформацію про продукт опубліковано в обраних місцях.","help":"Продукт не потрібен — досить опису того, що ти збираєшся зробити."},"es":{"question":"He publicado una breve información sobre el producto en los lugares elegidos.","help":"No necesitas el producto: basta con describir lo que piensas hacer."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
