update public.stage_fields f set translations = '{"en":{"question":"Who was interested in your idea?","help":"Who reacted, what did they ask, were they the people you had in mind?"},"de":{"question":"Wen hat deine Idee interessiert?","help":"Wer hat reagiert, was wurde gefragt, waren es die Menschen, um die es ging?"},"uk":{"question":"Кого зацікавила твоя ідея?","help":"Хто відреагував, про що питав, чи це були ті люди, про яких ішлося?"},"es":{"question":"¿A quién le interesó tu idea?","help":"¿Quién reaccionó, qué preguntó, eran las personas a las que te dirigías?"}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'idea' and t.version = 1 and c.key = 'b2c' and p.key = 'pozyskanie-klientow'
