update public.stage_fields f set translations = '{"en":{"question":"How many people said they wanted to use it?","config":{"unit":"people"}},"de":{"question":"Wie viele Personen haben angegeben, es nutzen zu wollen?","config":{"unit":"Personen"}},"uk":{"question":"Скільки людей заявили бажання скористатися?","config":{"unit":"осіб"}},"es":{"question":"¿Cuántas personas dijeron que querían usarlo?","config":{"unit":"personas"}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
