update public.stage_subpoints s set translations = '{"en":{"title":"Calculate the cost of winning one customer"},"de":{"title":"Berechne die Kosten für die Gewinnung eines Kunden"},"uk":{"title":"Порахуй вартість здобуття одного клієнта"},"es":{"title":"Calcula el coste de conseguir un cliente"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
