update public.stage_fields f set translations = '{"en":{"question":"How much did reaching these people cost?","help":"Ads, materials, trade fair tickets. If it cost nothing, enter 0.","config":{"unit":"$"}},"de":{"question":"Was hat es gekostet, diese Personen zu erreichen?","help":"Anzeigen, Materialien, Messetickets. Wenn es nichts gekostet hat, trag 0 ein.","config":{"unit":"€"}},"uk":{"question":"Скільки коштувало дістатися до цих людей?","help":"Реклама, матеріали, квитки на ярмарки. Якщо нічого не коштувало, впиши 0.","config":{"unit":"грн"}},"es":{"question":"¿Cuánto costó llegar a estas personas?","help":"Anuncios, materiales, entradas a ferias. Si no costó nada, escribe 0.","config":{"unit":"€"}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'idea' and t.version = 1 and c.key = 'b2c' and p.key = 'pozyskanie-klientow'
    and s.key = 'koszt-klienta' and f.key = 'wydane';
update public.stage_fields f set translations = '{"en":{"question":"How much did winning one interested person cost?","help":"This is the cost of winning one customer (in the industry: CAC). Enter the amount spent and the number of interested people — the result calculates itself.","config":{"unit":"$","calc":{"op":"quotient","inputs":[{"key":"wydane","label":"Money spent","unit":"$"},{"key":"osoby","label":"Interested people"}]}}},"de":{"question":"Was hat die Gewinnung einer interessierten Person gekostet?","help":"Das sind die Kosten für die Gewinnung eines Kunden (in der Branche: CAC). Trag den ausgegebenen Betrag und die Zahl der Interessierten ein — das Ergebnis wird automatisch berechnet.","config":{"unit":"€","calc":{"op":"quotient","inputs":[{"key":"wydane","label":"Ausgegebenes Geld","unit":"€"},{"key":"osoby","label":"Interessierte Personen"}]}}},"uk":{"question":"Скільки коштувало здобуття однієї зацікавленої людини?","help":"Це вартість здобуття одного клієнта (у галузі: CAC). Впиши витрачену суму й кількість зацікавлених людей — результат порахується сам.","config":{"unit":"грн","calc":{"op":"quotient","inputs":[{"key":"wydane","label":"Витрачені гроші","unit":"грн"},{"key":"osoby","label":"Зацікавлені люди"}]}}},"es":{"question":"¿Cuánto costó conseguir a una persona interesada?","help":"Es el coste de conseguir un cliente (en el sector: CAC). Escribe lo gastado y el número de personas interesadas: el resultado se calcula solo.","config":{"unit":"€","calc":{"op":"quotient","inputs":[{"key":"wydane","label":"Dinero gastado","unit":"€"},{"key":"osoby","label":"Personas interesadas"}]}}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'idea' and t.version = 1 and c.key = 'b2c' and p.key = 'pozyskanie-klientow'
    and s.key = 'koszt-klienta' and f.key = 'cac';
update public.stage_fields f set translations = '{"en":{"question":"At this cost, does it pay off at all?","help":"Compare it with the price you''re planning. If winning a customer costs more than they will pay — you have a problem to solve now, not later."},"de":{"question":"Lohnt sich das bei diesen Kosten überhaupt?","help":"Vergleiche es mit dem geplanten Preis. Wenn die Gewinnung eines Kunden mehr kostet, als er zahlt, hast du ein Problem, das jetzt gelöst werden muss — nicht später."},"uk":{"question":"Чи за такої вартості це взагалі вигідно?","help":"Порівняй із ціною, яку плануєш. Якщо здобуття клієнта коштує більше, ніж він заплатить, — у тебе проблема, яку треба розв’язати зараз, а не пізніше."},"es":{"question":"¿Compensa siquiera con este coste?","help":"Compáralo con el precio que planeas. Si conseguir un cliente cuesta más de lo que pagará, tienes un problema que resolver ahora, no más tarde."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'idea' and t.version = 1 and c.key = 'b2c' and p.key = 'pozyskanie-klientow'
    and s.key = 'koszt-klienta' and f.key = 'czy-oplaca';
update public.stage_subpoints s set translations = '{"en":{"title":"Pick one main way of reaching people"},"de":{"title":"Wähle einen Hauptweg, um Kunden zu erreichen"},"uk":{"title":"Обери один головний спосіб охоплення"},"es":{"title":"Elige una forma principal de llegar a los clientes"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'idea' and t.version = 1
    and c.key = 'b2c' and p.key = 'pozyskanie-klientow' and s.key = 'glowny-kanal';
update public.stage_fields f set translations = '{"en":{"question":"Which place gave the best and cheapest results?"},"de":{"question":"Welcher Ort hat die besten und günstigsten Ergebnisse gebracht?"},"uk":{"question":"Яке місце дало найкращі й найдешевші результати?"},"es":{"question":"¿Qué lugar dio los mejores resultados y más baratos?"}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'idea' and t.version = 1 and c.key = 'b2c' and p.key = 'pozyskanie-klientow'
    and s.key = 'glowny-kanal' and f.key = 'glowny';
update public.stage_fields f set translations = '{"en":{"question":"Which one are you keeping as a backup?","help":"One channel is a risk. A second one in reserve costs little and saves you when the first stops working."},"de":{"question":"Welchen behältst du als Reserve?","help":"Ein Kanal ist ein Risiko. Ein zweiter in Reserve kostet wenig und rettet dich, wenn der erste nicht mehr funktioniert."},"uk":{"question":"Яке залишаєш як запасне?","help":"Один канал — це ризик. Другий у запасі коштує небагато, а рятує, коли перший перестане працювати."},"es":{"question":"¿Cuál dejas de reserva?","help":"Un solo canal es un riesgo. Un segundo de reserva cuesta poco y te salva cuando el primero deja de funcionar."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'idea' and t.version = 1 and c.key = 'b2c' and p.key = 'pozyskanie-klientow'
    and s.key = 'glowny-kanal' and f.key = 'zapasowy';
update public.stage_points p set translations = '{"en":{"title":"Assess willingness to pay","guide_body":"Separate the payer from the user, compare alternatives:\nFind out who pays for the product and who uses it. Using our example of an innovative final-exam prep course: the payer may be a parent, and the user a student in the final year. This is one of the most important elements of running an effective business. Knowing who is who decides whether the product survives. The payer looks for business value, which is why in this point we also compare the cost of the alternatives payers currently use. The user looks for convenience, ease of use and a solution to the problem. This information will let you adjust, among other things, the product''s marketing and its real value.\nCollect and categorize the objections typical of individual purchases:\nEstimate LTV (how much a customer will pay in total over the whole time they use it) and compare it with CAC (the cost of winning one customer):\nLTV (Lifetime value) is the total revenue or profit a customer generates for the company over the whole cycle of cooperation. It''s a measure of how profitable a customer is. It helps determine how much winning one user may cost.\nThe LTV formula:\nLTV = Average order value * Average number of orders per year * Average length of cooperation\nExample:\nAverage value of one order (one transaction) = $25\nAverage number of orders per year = 2 times\nAverage length of cooperation with the customer = 4 years\nLTV = $25 * 2 * 4 = $200  (That''s what the customer is worth over the period of cooperation.)\nCAC is the average cost of winning one customer, calculated in point one. As a reminder: CAC = total marketing costs / number of customers won.\nFinally, you divide LTV by CAC and enter the result in the gap."},"de":{"title":"Schätze die Zahlungsbereitschaft ein","guide_body":"Trenne Zahlende von Nutzern, vergleiche Alternativen:\nFinde heraus, wer für das Produkt bezahlt und wer es nutzt. In unserem Beispiel eines innovativen Abiturkurses kann ein Elternteil zahlen und ein Abiturient das Produkt nutzen. Das ist einer der wichtigsten Punkte für ein erfolgreiches Geschäft. Zu wissen, wer wer ist, entscheidet über das Überleben des Produkts. Wer zahlt, sucht geschäftlichen Wert, deshalb vergleichen wir in diesem Punkt auch die Kosten der Alternativen, die die Zahlenden heute nutzen. Wer nutzt, sucht Bequemlichkeit, eine intuitive Bedienung und die Lösung des Problems. Mit diesen Informationen kannst du u. a. das Marketing des Produkts und seinen tatsächlichen Wert anpassen.\nSammle typische Einwände bei Privatkäufen und ordne sie in Kategorien:\nSchätze den LTV (was Kunden insgesamt während der gesamten Nutzung zahlen) und stelle ihn dem CAC gegenüber (Kosten für die Gewinnung eines Kunden):\nLTV (Lifetime Value) ist der gesamte Umsatz oder Gewinn, den ein Kunde während der gesamten Zusammenarbeit für die Firma erzeugt. Er misst, wie rentabel ein Kunde ist. Er hilft zu bestimmen, was die Gewinnung eines Nutzers kosten darf.\nFormel für den LTV:\nLTV = durchschnittlicher Bestellwert * durchschnittliche Zahl der Bestellungen pro Jahr * durchschnittliche Dauer der Zusammenarbeit\nBeispiel:\nDurchschnittlicher Wert einer Bestellung (einer Transaktion) = 25 €\nDurchschnittliche Zahl der Bestellungen pro Jahr = 2\nDurchschnittliche Dauer der Zusammenarbeit = 4 Jahre\nLTV = 25 € * 2 * 4 = 200 € (So viel ist ein Kunde über die Dauer der Zusammenarbeit wert.)\nCAC sind die durchschnittlichen Kosten für die Gewinnung eines Kunden, berechnet im ersten Punkt. Zur Erinnerung: CAC = gesamte Marketingkosten / Zahl der gewonnenen Kunden.\nZum Schluss teilst du den LTV durch den CAC und trägst das Ergebnis in das Feld ein."},"uk":{"title":"Оціни готовність платити","guide_body":"Відокрем платника від користувача, порівняй альтернативи:\nДізнайся, хто платить за продукт, а хто ним користується. На нашому прикладі інноваційного курсу підготовки до ЗНО: платником можуть бути батьки, а користувачем — випускник. Це один із найважливіших елементів успішного бізнесу. Знання, хто є хто, вирішує, чи виживе продукт. Платник шукає бізнесової цінності, тому в цьому пункті ми порівнюємо також вартість альтернатив, якими зараз користуються платники. Користувач шукає зручності, інтуїтивності й розв’язання проблеми. Ця інформація допоможе тобі, зокрема, налаштувати маркетинг продукту та його реальну цінність.\nЗбери й розклади за категоріями заперечення, типові для індивідуальних покупок:\nОціни LTV (скільки клієнт заплатить разом за весь час користування) і зістав із CAC (вартість здобуття одного клієнта):\nLTV (Lifetime value) — це загальний дохід або прибуток, який клієнт приносить компанії за весь цикл співпраці. Це міра того, наскільки вигідний клієнт. Допомагає визначити, скільки може коштувати здобуття одного користувача.\nФормула LTV:\nLTV = Середня вартість замовлення * Середня кількість замовлень на рік * Середній час співпраці\nПриклад:\nСередня вартість одного замовлення (однієї транзакції) = 1000 грн\nСередня кількість замовлень на рік = 2 рази\nСередній час співпраці з клієнтом = 4 роки\nLTV = 1000 грн * 2 * 4 = 8000 грн (Стільки вартий клієнт за час співпраці.)\nCAC — це середня вартість здобуття одного клієнта, порахована в першому пункті. Нагадаємо: CAC = загальні витрати на маркетинг / кількість здобутих клієнтів.\nНасамкінець ділиш LTV на CAC і вписуєш отриманий результат у поле."},"es":{"title":"Valora la disposición a pagar","guide_body":"Separa a quien paga de quien lo usa y compara alternativas:\nAverigua quién paga el producto y quién lo usa. Siguiendo nuestro ejemplo del curso innovador de preparación para la selectividad: quien paga puede ser el progenitor, y quien lo usa, el alumno de último curso. Es uno de los elementos más importantes de un negocio que funcione. Saber quién es quién decide la supervivencia del producto. Quien paga busca valor, por eso en este punto comparamos también el coste de las alternativas que usan hoy quienes pagan. Quien lo usa busca comodidad, facilidad de uso y resolver su problema. Esta información te permitirá ajustar, entre otras cosas, el marketing del producto y su valor real.\nReúne y clasifica las objeciones típicas de las compras particulares:\nEstima el LTV (lo que pagará el cliente en total durante todo el tiempo de uso) y compáralo con el CAC (coste de conseguir un cliente):\nEl LTV (Lifetime value) es el ingreso o beneficio total que un cliente genera para la empresa durante toda la relación. Mide lo rentable que es un cliente. Ayuda a determinar cuánto puede costar conseguir un usuario.\nFórmula del LTV:\nLTV = Valor medio del pedido * Número medio de pedidos al año * Duración media de la relación\nEjemplo:\nValor medio de un pedido (una transacción) = 25 €\nNúmero medio de pedidos al año = 2\nDuración media de la relación con el cliente = 4 años\nLTV = 25 € * 2 * 4 = 200 € (Esto es lo que vale un cliente durante la relación.)\nEl CAC es el coste medio de conseguir un cliente, calculado en el primer punto. Como recordatorio: CAC = costes totales de marketing / número de clientes conseguidos.\nPor último, divides el LTV entre el CAC y escribes el resultado en el campo."}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'idea' and t.version = 1
    and c.key = 'b2c' and p.key = 'gotowosc-do-zaplaty';
update public.stage_subpoints s set translations = '{"en":{"title":"Collect the objections and group them"},"de":{"title":"Sammle Einwände und gruppiere sie"},"uk":{"title":"Збери заперечення й згрупуй їх"},"es":{"title":"Reúne las objeciones y agrúpalas"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'idea' and t.version = 1
    and c.key = 'b2c' and p.key = 'gotowosc-do-zaplaty' and s.key = 'obiekcje';
update public.stage_fields f set translations = '{"en":{"question":"What stops people from buying?","help":"For each one, add where it comes from: lack of trust in the brand, no urgent need, or a comparison with an easily available alternative."},"de":{"question":"Was hält Menschen vom Kauf ab?","help":"Ergänze bei jedem, woraus er sich ergibt: fehlendes Vertrauen in die Marke, kein dringender Bedarf oder der Vergleich mit einer leicht verfügbaren Alternative."},"uk":{"question":"Що стримує людей від покупки?","help":"Біля кожного допиши, з чого воно випливає: брак довіри до бренду, відсутність нагальної потреби чи порівняння з легкодоступною альтернативою."},"es":{"question":"¿Qué frena a la gente a la hora de comprar?","help":"En cada una, añade de dónde viene: falta de confianza en la marca, ausencia de necesidad urgente o comparación con una alternativa fácil de conseguir."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'idea' and t.version = 1 and c.key = 'b2c' and p.key = 'gotowosc-do-zaplaty'
    and s.key = 'obiekcje' and f.key = 'lista';
update public.stage_subpoints s set translations = '{"en":{"title":"Estimate the customer''s value and compare it with the cost"},"de":{"title":"Schätze den Kundenwert und stelle ihn den Kosten gegenüber"},"uk":{"title":"Оціни цінність клієнта й зістав її з вартістю"},"es":{"title":"Estima el valor del cliente y compáralo con el coste"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'idea' and t.version = 1
    and c.key = 'b2c' and p.key = 'gotowosc-do-zaplaty' and s.key = 'ltv-vs-cac';
update public.stage_fields f set translations = '{"en":{"question":"How much will the customer pay you in total over the whole time they use it?","help":"This is the customer''s value over the whole period of use (in the industry: LTV). Enter three numbers — the result calculates itself.","config":{"unit":"$","calc":{"op":"product","inputs":[{"key":"zamowienie","label":"Average purchase value","unit":"$"},{"key":"zakupy","label":"Purchases per year"},{"key":"lata","label":"How many years they stay a customer"}]}}},"de":{"question":"Wie viel zahlen dir Kunden insgesamt während der gesamten Nutzung?","help":"Das ist der Kundenwert über die gesamte Nutzungsdauer (in der Branche: LTV). Trag drei Zahlen ein — das Ergebnis wird automatisch berechnet.","config":{"unit":"€","calc":{"op":"product","inputs":[{"key":"zamowienie","label":"Durchschnittlicher Kaufwert","unit":"€"},{"key":"zakupy","label":"Käufe pro Jahr"},{"key":"lata","label":"Wie viele Jahre jemand Kunde bleibt"}]}}},"uk":{"question":"Скільки клієнт заплатить тобі разом за весь час користування?","help":"Це цінність клієнта за весь період користування (у галузі: LTV). Впиши три числа — результат порахується сам.","config":{"unit":"грн","calc":{"op":"product","inputs":[{"key":"zamowienie","label":"Середня вартість покупки","unit":"грн"},{"key":"zakupy","label":"Покупок на рік"},{"key":"lata","label":"Скільки років залишається клієнтом"}]}}},"es":{"question":"¿Cuánto te pagará el cliente en total durante todo el tiempo de uso?","help":"Es el valor del cliente durante todo el periodo de uso (en el sector: LTV). Escribe tres números: el resultado se calcula solo.","config":{"unit":"€","calc":{"op":"product","inputs":[{"key":"zamowienie","label":"Valor medio de compra","unit":"€"},{"key":"zakupy","label":"Compras al año"},{"key":"lata","label":"Años que sigue siendo cliente"}]}}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'idea' and t.version = 1 and c.key = 'b2c' and p.key = 'gotowosc-do-zaplaty'
    and s.key = 'ltv-vs-cac' and f.key = 'ltv';
update public.stage_fields f set translations = '{"en":{"question":"How does this amount compare with the cost of winning one customer from the point “How to find customers”?","help":"The accepted rule says that what a customer pays in total should be several times higher than the cost of winning them. If it''s the other way round, the business loses on every customer."},"de":{"question":"Wie steht dieser Betrag im Verhältnis zu den Kosten für die Gewinnung eines Kunden aus dem Punkt „Wie du Kunden findest“?","help":"Die gängige Regel lautet: Was Kunden insgesamt zahlen, sollte ein Mehrfaches der Kosten für ihre Gewinnung betragen. Ist es umgekehrt, verliert das Geschäft an jedem Kunden."},"uk":{"question":"Як ця сума виглядає на тлі вартості здобуття одного клієнта з пункту «Як знайти клієнтів»?","help":"Прийняте правило каже, що те, що клієнт заплатить разом, має бути в кілька разів більшим за вартість його здобуття. Якщо навпаки, бізнес втрачає на кожному клієнті."},"es":{"question":"¿Cómo queda esta cifra frente al coste de conseguir un cliente del punto «Cómo encontrar clientes»?","help":"La regla habitual dice que lo que paga el cliente en total debería ser varias veces mayor que el coste de conseguirlo. Si es al revés, el negocio pierde con cada cliente."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'idea' and t.version = 1 and c.key = 'b2c' and p.key = 'gotowosc-do-zaplaty'
    and s.key = 'ltv-vs-cac' and f.key = 'wniosek';
update public.stage_categories c set translations = '{"en":{"title":"Hardware","intro":"Check whether the device can be built and manufactured in a way that makes sense technically and financially. You''re not building the finished product yet — you''re catching the risks: feasibility, costs, time to market, demand and regulations."},"de":{"title":"Hardware","intro":"Prüfe, ob sich das Gerät so bauen und herstellen lässt, dass es technisch und finanziell Sinn ergibt. Du baust noch kein fertiges Produkt — du findest die Risiken: Machbarkeit, Kosten, Markteintrittszeit, Nachfrage und Vorschriften."},"uk":{"title":"Hardware","intro":"Перевір, чи можна збудувати й виготовити пристрій так, щоб це мало сенс технічно й фінансово. Ти ще не будуєш готового продукту — ти виявляєш ризики: здійсненність, витрати, час виходу на ринок, попит і правила."},"es":{"title":"Hardware","intro":"Comprueba si el dispositivo se puede construir y fabricar de forma que tenga sentido técnico y económico. Todavía no construyes el producto final: detectas los riesgos: viabilidad, costes, plazo de salida al mercado, demanda y normativa."}}'::jsonb
  from public.stage_templates t where c.template_id = t.id and t.key = 'idea' and t.version = 1 and c.key = 'hardware';
update public.stage_points p set translations = '{"en":{"title":"Confirm the problem and the need for a physical device","guide_body":"Building a physical product requires validating technical feasibility, production costs, demand and compliance requirements before starting to build working prototypes. At the Idea Stage the process starts with interviewing potential users and making sure that the problem is real and that solving it requires a physical device rather than a simpler digital solution or a service. Next, a form concept (form factor) is created as sketches, 3D renders or simple cardboard or 3D-printed mock-ups (a looks-like model) to set the planned size, ergonomics and way of interacting, and it is then shown to customers to collect feedback and check whether they understand how the concept works."},"de":{"title":"Bestätige das Problem und den Bedarf an einem physischen Gerät","guide_body":"Der Bau eines physischen Produkts erfordert die Validierung von technischer Machbarkeit, Herstellungskosten, Nachfrage und Konformitätsanforderungen, bevor funktionierende Prototypen gebaut werden. In der Idea-Phase beginnt der Prozess mit Interviews mit potenziellen Nutzern, um sicherzustellen, dass das Problem real ist und dass für seine Lösung ein physisches Gerät nötig ist — und keine einfachere digitale Lösung oder Dienstleistung. Danach entsteht ein Formkonzept (Form-Factor) als Skizzen, 3D-Visualisierungen oder einfache Modelle aus Karton oder 3D-Druck (Looks-like-Modell), um Größe, Ergonomie und Interaktion festzulegen. Dieses Konzept wird Kunden gezeigt, um Meinungen zu sammeln und zu prüfen, ob sie verstehen, wie es funktioniert."},"uk":{"title":"Підтверди проблему й потребу у фізичному пристрої","guide_body":"Створення фізичного продукту вимагає валідації технічної здійсненності, вартості виробництва, попиту та вимог відповідності ще до створення робочих прототипів. На етапі Idea процес починається з інтерв’ю з потенційними користувачами, щоб переконатися, що проблема реальна і що для її розв’язання потрібен фізичний пристрій, а не простіше цифрове рішення чи послуга. Далі створюють концепцію форми (form-factor) у вигляді ескізів, 3D-візуалізацій або простих макетів із картону чи 3D-друку (looks-like model), щоб визначити запланований розмір, ергономіку й спосіб взаємодії, а потім показують її клієнтам, щоб зібрати думки й перевірити, чи розуміють вони, як працює концепт."},"es":{"title":"Confirma el problema y la necesidad de un dispositivo físico","guide_body":"Construir un producto físico exige validar la viabilidad técnica, los costes de fabricación, la demanda y los requisitos de conformidad antes de construir prototipos que funcionen. En la fase Idea, el proceso empieza con entrevistas a posibles usuarios para asegurarse de que el problema es real y de que resolverlo requiere un dispositivo físico, y no una solución digital o un servicio más sencillos. Después se crea un concepto de forma (form-factor) con bocetos, visualizaciones 3D o maquetas sencillas de cartón o impresión 3D (looks-like model) para fijar el tamaño previsto, la ergonomía y la forma de interacción, y se presenta a los clientes para recoger opiniones y comprobar si entienden cómo funciona el concepto."}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'idea' and t.version = 1
    and c.key = 'hardware' and p.key = 'problem-i-potrzeba-fizyczna';
update public.stage_subpoints s set translations = '{"en":{"title":"Justify the need to build hardware"},"de":{"title":"Begründe, warum Hardware nötig ist"},"uk":{"title":"Обґрунтуй потребу створити пристрій"},"es":{"title":"Justifica por qué hace falta hardware"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'idea' and t.version = 1
    and c.key = 'hardware' and p.key = 'problem-i-potrzeba-fizyczna' and s.key = 'dlaczego-sprzet';
update public.stage_fields f set translations = '{"en":{"question":"Why does your solution require a physical device?","help":"Make sure the problem can''t be solved more simply — with just an app, a service or software. Hardware is an order of magnitude more expensive and slower."},"de":{"question":"Warum braucht deine Lösung ein physisches Gerät?","help":"Stelle sicher, dass sich das Problem nicht einfacher lösen lässt — nur mit einer App, einem Dienst oder Software. Hardware ist um eine Größenordnung teurer und langsamer."},"uk":{"question":"Чому твоє рішення потребує фізичного пристрою?","help":"Переконайся, що проблему не можна розв’язати простіше — самим застосунком, послугою чи програмою. Залізо на порядок дорожче й повільніше."},"es":{"question":"¿Por qué tu solución necesita un dispositivo físico?","help":"Asegúrate de que el problema no se pueda resolver de forma más sencilla, solo con una app, un servicio o software. El hardware es un orden de magnitud más caro y lento."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'idea' and t.version = 1 and c.key = 'hardware' and p.key = 'problem-i-potrzeba-fizyczna'
    and s.key = 'dlaczego-sprzet' and f.key = 'uzasadnienie';
update public.stage_subpoints s set translations = '{"en":{"title":"Create a form concept"},"de":{"title":"Erstelle ein Formkonzept"},"uk":{"title":"Створи концепцію форми"},"es":{"title":"Crea un concepto de forma"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'idea' and t.version = 1
    and c.key = 'hardware' and p.key = 'problem-i-potrzeba-fizyczna' and s.key = 'koncepcja-formy';
update public.stage_fields f set translations = '{"en":{"question":"What should the planned size, form and way of interacting with the product be?"},"de":{"question":"Welche Größe, Form und Interaktion soll das Produkt haben?"},"uk":{"question":"Який має бути запланований розмір, форма і спосіб взаємодії з продуктом?"},"es":{"question":"¿Qué tamaño, forma y modo de interacción tendrá el producto?"}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'idea' and t.version = 1 and c.key = 'hardware' and p.key = 'problem-i-potrzeba-fizyczna'
    and s.key = 'koncepcja-formy' and f.key = 'opis-formy';
update public.stage_fields f set translations = '{"en":{"question":"Sketches, a 3D render or photos of a mock-up","help":"A sketch or a render is enough — you don''t have to build anything. A cardboard mock-up or a 3D print will also do."},"de":{"question":"Skizzen, 3D-Rendering oder Fotos eines Modells","help":"Eine Skizze oder ein Rendering reicht — du musst nichts bauen. Ein Kartonmodell oder ein 3D-Druck eignen sich auch."},"uk":{"question":"Ескізи, 3D-рендер або фото макета","help":"Досить ескізу чи рендера — нічого будувати не треба. Картонний макет чи 3D-друк теж підійдуть."},"es":{"question":"Bocetos, render 3D o fotos de una maqueta","help":"Basta un boceto o un render: no tienes que construir nada. Una maqueta de cartón o una impresión 3D también sirven."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'idea' and t.version = 1 and c.key = 'hardware' and p.key = 'problem-i-potrzeba-fizyczna'
    and s.key = 'koncepcja-formy' and f.key = 'makieta';
update public.stage_subpoints s set translations = '{"en":{"title":"Collect feedback on the concept"},"de":{"title":"Sammle Meinungen zum Konzept"},"uk":{"title":"Збери думки про концепцію"},"es":{"title":"Recoge opiniones sobre el concepto"}}'::jsonb
