update public.stage_subpoints s set translations = '{"en":{"title":"Discuss the concept with an engineer"},"de":{"title":"Besprich das Konzept mit einer Ingenieurin oder einem Ingenieur"},"uk":{"title":"Обговори концепцію з інженером"},"es":{"title":"Consulta el concepto con un ingeniero"}}'::jsonb
