update public.stage_fields f set translations = '{"en":{"question":"What did they say about combining these components in the intended enclosure?"},"de":{"question":"Was wurde zur Kombination dieser Komponenten im geplanten Gehäuse gesagt?"},"uk":{"question":"Що було сказано про поєднання цих компонентів у запланованому корпусі?"},"es":{"question":"¿Qué te dijo sobre combinar estos componentes en la carcasa prevista?"}}'::jsonb
