update public.stage_fields f set translations = '{"en":{"question":"Which function is surrounded by the most uncertainty?","help":"E.g. battery life, sensor precision, heat dissipation. This is what you''ll deal with first."},"de":{"question":"Bei welcher Funktion ist die Unsicherheit am größten?","help":"Z. B. Akkulaufzeit, Sensorgenauigkeit, Wärmeabfuhr. Darum kümmerst du dich zuerst."},"uk":{"question":"Щодо якої функції найбільше невизначеності?","help":"Напр. час роботи від батареї, точність датчика, відведення тепла. Цим займешся насамперед."},"es":{"question":"¿En qué función hay más incertidumbre?","help":"P. ej. autonomía de la batería, precisión del sensor, disipación del calor. Es lo primero de lo que te ocuparás."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
