update public.stage_fields f set translations = '{"en":{"question":"List the known components with their retail prices."},"de":{"question":"Liste die bekannten Komponenten mit Einzelhandelspreisen auf."},"uk":{"question":"Випиши відомі компоненти з роздрібними цінами."},"es":{"question":"Enumera los componentes conocidos con sus precios minoristas."}}'::jsonb
