update public.stage_subpoints s set translations = '{"en":{"title":"Estimate the unit cost"},"de":{"title":"Schätze die Stückkosten"},"uk":{"title":"Оціни собівартість одиниці"},"es":{"title":"Estima el coste unitario"}}'::jsonb
