update public.stage_fields f set translations = '{"en":{"question":"How much do the components alone cost?","config":{"unit":"$"}},"de":{"question":"Was kosten die Komponenten allein?","config":{"unit":"€"}},"uk":{"question":"Скільки коштують самі компоненти?","config":{"unit":"грн"}},"es":{"question":"¿Cuánto cuestan solo los componentes?","config":{"unit":"€"}}}'::jsonb
