update public.stage_fields f set translations = '{"en":{"question":"A price increase of which component would most threaten profitability?","help":"E.g. a custom display, an expensive battery, an enclosure requiring an injection mold."},"de":{"question":"Der Preisanstieg welcher Komponente würde die Rentabilität am stärksten gefährden?","help":"Z. B. ein nicht standardmäßiges Display, ein teurer Akku, ein Gehäuse, das eine Spritzgussform erfordert."},"uk":{"question":"Подорожчання якого компонента найбільше загрожуватиме рентабельності?","help":"Напр. нестандартний дисплей, дорога батарея, корпус, що потребує ливарної форми."},"es":{"question":"¿La subida de precio de qué componente pondría más en riesgo la rentabilidad?","help":"P. ej. una pantalla no estándar, una batería cara, una carcasa que requiere molde de inyección."}}'::jsonb
