update public.stage_fields f set translations = '{"en":{"question":"Choose the changes with the greatest impact on the product''s value.","help":"Choose the changes with the greatest impact on the product''s value. Link the goal required in this point and add the proof in the goal card."},"de":{"question":"Wähle die Änderungen mit dem größten Einfluss auf den Wert des Produkts.","help":"Wähle die Änderungen mit dem größten Einfluss auf den Wert des Produkts. Verknüpfe das in diesem Punkt verlangte Ziel und füge den Nachweis in der Zielkarte hinzu."},"uk":{"question":"Обери зміни з найбільшим впливом на цінність продукту.","help":"Обери зміни з найбільшим впливом на цінність продукту. Прикріпи ціль, потрібну в цьому пункті, і додай доказ у картці цілі."},"es":{"question":"Elige los cambios con más impacto en el valor del producto.","help":"Elige los cambios con más impacto en el valor del producto. Vincula el objetivo requerido en este punto y añade la prueba en la tarjeta del objetivo."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'mvp' and t.version = 1 and c.key = 'general' and p.key = 'general-opracuj-kierunek-dalszego-rozwoju'
    and s.key = 'ustal-najwazniejsze-poprawki' and f.key = 'note';
