update public.stage_subpoints s set translations = '{"en":{"title":"Define the next direction of action"},"de":{"title":"Lege die nächste Handlungsrichtung fest"},"uk":{"title":"Визнач наступний напрям дій"},"es":{"title":"Decide la siguiente dirección de trabajo"}}'::jsonb
