  where p.category_id = c.id and c.template_id = t.id and t.key = 'mvp' and t.version = 1
    and c.key = 'general' and p.key = 'general-ponownie-skonsultuj-rozwiazanie';
update public.stage_subpoints s set translations = '{"en":{"title":"Introduce the most important changes"},"de":{"title":"Setze die wichtigsten Änderungen um"},"uk":{"title":"Внеси найважливіші зміни"},"es":{"title":"Aplica los cambios más importantes"}}'::jsonb
