update public.stage_subpoints s set translations = '{"en":{"title":"Make the solution available to users again"},"de":{"title":"Stelle die Lösung den Nutzern erneut bereit"},"uk":{"title":"Знову надай рішення користувачам"},"es":{"title":"Vuelve a poner la solución a disposición de los usuarios"}}'::jsonb
