update public.stage_categories c set translations = '{"en":{"title":"SaaS","intro":"A layer for a subscription product — launch, usage and model."},"de":{"title":"SaaS","intro":"Ebene für ein Abo-Produkt — Start, Nutzung und Modell."},"uk":{"title":"SaaS","intro":"Шар для продукту з підпискою — запуск, використання й модель."},"es":{"title":"SaaS","intro":"Capa para un producto de suscripción: lanzamiento, uso y modelo."}}'::jsonb
