update public.stage_subpoints s set translations = '{"en":{"title":"Run defect interviews with users"},"de":{"title":"Führe Fehlerinterviews mit Nutzern durch"},"uk":{"title":"Проведи інтерв’ю про несправності з користувачами"},"es":{"title":"Haz entrevistas sobre fallos con los usuarios"}}'::jsonb
