update public.stage_subpoints s set translations = '{"en":{"title":"Get firm orders for a larger volume"},"de":{"title":"Hol dir feste Bestellungen für ein größeres Volumen"},"uk":{"title":"Отримай тверді замовлення на більший обсяг"},"es":{"title":"Consigue pedidos firmes para un volumen mayor"}}'::jsonb
