update public.stage_subpoints s set translations = '{"en":{"title":"Decide on the mass order"},"de":{"title":"Entscheide über die Massenbestellung"},"uk":{"title":"Ухвали рішення про масове замовлення"},"es":{"title":"Decide sobre el pedido masivo"}}'::jsonb
