update public.stage_subpoints s set translations = '{"en":{"title":"Identify the moment of key value"},"de":{"title":"Finde den Moment des Schlüsselnutzens"},"uk":{"title":"Визнач момент ключової цінності"},"es":{"title":"Identifica el momento de valor clave"}}'::jsonb
